dslRule:
/*!
@id: eclipse.jface.text.printStackTrace
@description: Replace e.printStackTrace() with System.err.println(e) for cleaner error reporting, especially in example code.
@severity: HINT
*/
$e.printStackTrace() :: instanceof($e, "java.lang.Throwable")
=>
java.lang.System.err.println($e)
;;

beforeExample:
public class Example {
    public void foo() {
        try {
            int x = 1 / 0;
        } catch (ArithmeticException e) {
            e.printStackTrace();
        }
    }
}

afterExample:
public class Example {
    public void foo() {
        try {
            int x = 1 / 0;
        } catch (ArithmeticException e) {
            java.lang.System.err.println(e);
        }
    }
}

negativeExample:
public class NegativeExample {
    public void foo() {
        MyCustomLogger logger = new MyCustomLogger();
        try {
            int x = 1 / 0;
        } catch (ArithmeticException e) {
            logger.logError(e); // Should not match
        }
    }
}
class MyCustomLogger {
    public void logError(Throwable t) {
        // custom logging logic, not printStackTrace
    }
}
